class GwErrorBoundary extends React.Component {
  constructor(p) { super(p); this.state = { err: null }; }
  static getDerivedStateFromError(err) { return { err }; }
  componentDidCatch(err, info) { try { console.error("App crash:", err, info); } catch {} }
  render() {
    if (this.state.err) {
      return (
        <div style={{ minHeight: "100vh", background: "#F0F2F5", display: "flex", alignItems: "center", justifyContent: "center", padding: 24, fontFamily: "system-ui, sans-serif" }}>
          <div style={{ background: "#fff", borderRadius: 16, padding: "28px 24px", maxWidth: 360, textAlign: "center", boxShadow: "0 8px 30px rgba(0,0,0,.12)" }}>
            <div style={{ fontSize: 40 }}>😕</div>
            <div style={{ fontWeight: 800, fontSize: 17, color: "#111B21", marginTop: 10 }}>Something went wrong</div>
            <div style={{ fontSize: 13.5, color: "#667781", marginTop: 8, lineHeight: 1.5 }}>A small glitch stopped this screen. Your data is safe — just reload.</div>
            <button onClick={() => { try { window.location.href = "/"; } catch {} }} style={{ marginTop: 18, background: "#008069", color: "#fff", border: "none", borderRadius: 10, padding: "12px 22px", fontWeight: 800, fontSize: 14.5, cursor: "pointer" }}>↻ Reload app</button>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}
export default function App() {
  return <GwErrorBoundary><MobileLayoutStyles /><AppRoot /></GwErrorBoundary>;
}

// Shared by signed-in and public screens; horizontal scrolling stays inside rails.
function MobileLayoutStyles() {
  return <style>{`
    html,body,#root{margin:0;padding:0;width:100%;min-width:0;max-width:100%;}
    html,body{overflow-x:hidden;}
    @supports(overflow:clip){html,body{overflow-x:clip;}}
    *,*::before,*::after{box-sizing:border-box;}
    button,input,select,textarea{font-family:inherit;}
    .gw-public,.gw-public-main,.gw-event-grid,.gw-poster-card{min-width:0;max-width:100%;}
    .gw-poster-card{width:100%;overflow-wrap:anywhere;}
    .gw-category-rail{width:100%;min-width:0;max-width:100%;overscroll-behavior-x:contain;-webkit-overflow-scrolling:touch;}
    .gw-public-header{gap:12px;}
    .gw-public-actions{min-width:0;align-items:center;}
    .gw-public-actions button{white-space:nowrap;min-height:44px;}
    .gw-public-header>img{max-width:90px;flex-shrink:0;}
    @media(max-width:819px){
      .gw-event-grid{grid-template-columns:minmax(0,1fr)!important;gap:20px!important;}
      .gw-public-header{padding:10px 12px!important;gap:8px;}
      .gw-public-header>img{width:48px;height:34px!important;}
      .gw-public-actions{gap:6px!important;}
      .gw-public-actions button{padding:8px 10px!important;font-size:12px!important;}
      .gw-poster-card>div:last-child{padding:10px 2px 4px!important;}
      .gw-poster-card>div:last-child>div:first-child{font-size:16px!important;line-height:1.35!important;}
    }
    @media(max-width:359px){
      .gw-public-header{flex-wrap:wrap;}
      .gw-public-actions{flex:1;justify-content:flex-end;flex-wrap:wrap;}
    }
  `}</style>;
}

function AppRoot() {
  const [loading, setLoading] = useState(true);
  const [session, setSession] = useState(null);
  const [recovery, setRecovery] = useState(false);
  useEffect(() => {
    try { const sp = new URLSearchParams(window.location.search); const r = sp.get("ref"); if (r) localStorage.setItem("gw_ref", r.trim()); const gm = sp.get("game"); if (gm) localStorage.setItem("gw_open_game", gm.trim()); const spk = sp.get("spark"); if (spk) localStorage.setItem("gw_open_spark", spk.trim()); const ev = sp.get("event"); if (ev) localStorage.setItem("gw_event", ev.trim()); const reel = sp.get("reel"); if (reel) localStorage.setItem("gw_open_reel", reel.trim()); } catch {}
    supabase.auth.getSession().then(({ data }) => { setSession(data.session); setLoading(false); });
    const { data: sub } = supabase.auth.onAuthStateChange((e, s) => { setSession(s); if (e === "PASSWORD_RECOVERY") setRecovery(true); });
    if ("serviceWorker" in navigator) navigator.serviceWorker.register("/sw.js").catch(() => {});
    return () => sub.subscription.unsubscribe();
  }, []);
  if (loading) return <Shell><Splash /></Shell>;
  if (recovery) return <Shell><RecoverPassword onDone={() => setRecovery(false)} /></Shell>;
  let gtCode = null; try { gtCode = new URLSearchParams(window.location.search).get("gt"); } catch {}
  if (gtCode) return <Shell><GuestTicketPage code={gtCode} /></Shell>;
  if (!session) return <PublicLanding />;
  return <Shell><Main user={session.user} /></Shell>;
}

function useWide(bp = 1000) {
  const [w, setW] = useState(typeof window !== "undefined" ? window.innerWidth : 0);
  useEffect(() => { const f = () => setW(window.innerWidth); window.addEventListener("resize", f); return () => window.removeEventListener("resize", f); }, []);
  return w >= bp;
}
