  if (t === "snap") return "📷 Snap 🔥";
  if (t === "poll") return "📊 Poll";
  if (t === "file") return "📎 " + (m.body || "File");
  if (t === "location") return "📍 Location";
  if (t === "roomlink") return "💬 Shared a room";
  if (t === "gif") return "GIF";
  if (t === "event") return "🎟️ " + ((m.body || "Event").split("\n")[0]);
