                <div style={{ display: "flex", gap: 8 }}>{[1, 2, 3, 4, 5].map(n => <span key={n} onClick={() => setRStars(n)} style={{ fontSize: 30, cursor: "pointer", lineHeight: 1, filter: n <= rStars ? "none" : "grayscale(1) opacity(.35)" }}>⭐</span>)}</div>
