                <button onClick={submitRating} disabled={!rStars || rBusy} style={{ ...btn(W.teal, "#fff"), marginTop: 10, padding: "11px 18px", opacity: (!rStars || rBusy) ? .6 : 1 }}>{rBusy ? "Saving…" : (myRating || rDone) ? "Update rating" : "Submit rating"}</button>
