        {active ? <span onClick={e => { e.stopPropagation(); onPick("all"); }} style={{ fontSize: 15, color: W.soft, fontWeight: 800, padding: "0 2px" }}>✕</span> : <span style={{ opacity: .55 }}>▾</span>}
