  const other = (rows || []).filter(m => m.gender !== "male" && m.gender !== "female");
  const Head = (label, n, color) => <div style={{ fontWeight: 800, color: W.ink, fontSize: 15, marginTop: 22, paddingBottom: 7, borderBottom: `2px solid ${color}` }}>{label} ({n})</div>;
