                                  {m.avatar_url ? <img src={m.avatar_url} alt="" style={{ width: 28, height: 28, borderRadius: "50%", objectFit: "cover" }} /> : <span style={{ fontSize: 18 }}>👤</span>}
                                  <span style={{ fontWeight: 700, color: W.ink, fontSize: 13.5 }}>{m.full_name}</span>
