  const addPack = () => setPacks(p => [...(p || []), { id: "new_" + Date.now() + Math.random().toString(36).slice(2, 6), label: "New pack", credits: 10, price: 99, sort: (p && p.length ? Math.max(...p.map(x => x.sort || 0)) + 1 : 1), active: true, _new: true }]);
