        <button onClick={() => { setList(l => [...l, { q: "", a: "" }]); setSaved(false); }} style={{ ...btn("#fff", W.teal), border: `1px solid ${W.line}`, flex: 1, justifyContent: "center" }}><Plus size={14} />Add FAQ</button>
